package net.civeira.phylax.feature.observe.observedslo.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedslo.domain.ObservedSlo;
import net.civeira.phylax.feature.observe.observedslo.domain.valueobject.WindowDaysVO;

class WindowDaysValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of window days of observed slo")
  void test_window_days_value_holder_assign_plain_value() {
    Object holder = new Object();
    WindowDaysValueHolder<Object> value = new WindowDaysValueHolder<>(holder);
    Assertions.assertSame(holder, value.windowDays(1), "Setters must return the holder");
    Assertions.assertTrue(value.getWindowDaysValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getWindowDays().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of window days of observed slo")
  void test_window_days_value_holder_assign_value_object() {
    Object holder = new Object();
    WindowDaysValueHolder<Object> value = new WindowDaysValueHolder<>(holder);
    WindowDaysVO vo = WindowDaysVO.from(1);
    Assertions.assertFalse(value.getWindowDaysValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.windowDays(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getWindowDaysValue().orElseThrow());
    Assertions.assertSame(holder, value.windowDays(Optional.empty()));
    Assertions.assertFalse(value.getWindowDaysValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.windowDays(Optional.of(vo)));
    Assertions.assertSame(vo, value.getWindowDaysValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of window days of observed slo against the original")
  void test_window_days_value_holder_read() {
    Object holder = new Object();
    WindowDaysValueHolder<Object> value = new WindowDaysValueHolder<>(holder);
    WindowDaysVO vo = WindowDaysVO.from(1);
    WindowDaysVO other = WindowDaysVO.from(1);
    ObservedSlo original = Mockito.mock(ObservedSlo.class);
    Mockito.when(original.getWindowDaysValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readWindowDays(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readWindowDays(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.windowDays(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readWindowDays(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readWindowDays(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of window days of observed slo")
  void test_window_days_value_holder_unset() {
    Object holder = new Object();
    WindowDaysValueHolder<Object> value = new WindowDaysValueHolder<>(holder);
    WindowDaysVO vo = WindowDaysVO.from(1);
    value.windowDays(vo);
    Assertions.assertSame(holder, value.unsetWindowDaysIfMatches("windowDays_other"));
    Assertions.assertTrue(value.getWindowDaysValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetWindowDaysIfMatches("windowDays"));
    Assertions.assertFalse(value.getWindowDaysValue().isPresent(),
        "The field name must clear the value");
    value.windowDays(vo);
    Assertions.assertSame(holder, value.unsetWindowDays());
    Assertions.assertFalse(value.getWindowDaysValue().isPresent(), "Unset must clear the value");
  }
}
